/**
 * Unit tests for XYSeries.addOrUpdate
 */
public class XYSeries_addOrUpdate_TriageGen2Test {







    @Test
    public void testAddOrUpdate_NoDuplicates_NewItem_WithAutoSort() {
        // When autoSort is true, it uses the index from binarySearch to insert correctly
        XYSeries series = new XYSeries("Test", true, false);
        series.addOrUpdate(10.0, 100.0);
        series.addOrUpdate(5.0, 50.0); // This should be inserted at index 0 because of autoSort

        assertEquals(2, series.getItemCount());
        assertEquals(5.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(10.0, series.getX(1).doubleValue(), 0.001);
    }






