import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for XYSeries.addOrUpdate
 */
public class XYSeries_addOrUpdate_TriageGen2Test {









    @Test
    public void testAddOrUpdate_NoDuplicates_UpdateExisting() {
        // When X exists, it updates Y and returns the old item (cloned)
        XYSeries series = new XYSeries("Test", false, false);
        series.addOrUpdate(1.0, 10.0);

        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNotNull("Should return the overwritten item", overwritten);
        assertEquals(1.0, overwritten.getX().doubleValue(), 0.001);
        assertEquals(10.0, overwritten.getY().doubleValue(), 0.001);

        assertEquals(1, series.getItemCount());
        assertEquals(20.0, series.getY(0).doubleValue(), 0.001);
    }




}

