 */
public class XYSeries_addOrUpdate_TriageGen2Test {











    @Test
    public void testAddOrUpdate_ExceedMaximumItemCount() {
        // When new item is added and count > maximum, remove the first item
        XYSeries series = new XYSeries("Test", false, false);
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        series.addOrUpdate(3.0, 30.0); // Should trigger removal of index 0 (value 1.0)

        assertEquals(2, series.getItemCount());
        assertEquals(2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(3.0, series.getX(1).doubleValue(), 0.001);
    }


}

package org.jfree.data.xy;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
